const lessons=[{"sentences":[{"speaker":"A","text":"Attention all visitors to the modern art gallery today.","position":1,"audioStartSeconds":0,"audioEndSeconds":3.89675},{"speaker":"A","text":"The main exhibition hall on the second floor will close early for maintenance work.","position":2,"audioStartSeconds":4.09675,"audioEndSeconds":9.277916666666666},{"speaker":"A","text":"Staff members need to check the lighting equipment before tomorrow morning.","position":3,"audioStartSeconds":9.477916666666667,"audioEndSeconds":14.117125},{"speaker":"A","text":"Please move toward the ground floor gift shop by four o'clock.","position":4,"audioStartSeconds":14.317125,"audioEndSeconds":18.453708333333335},{"speaker":"A","text":"You can still view the sculpture garden outside until five o'clock.","position":5,"audioStartSeconds":18.653708333333334,"audioEndSeconds":22.893416666666667},{"speaker":"A","text":"We apologize for any inconvenience caused by this unexpected schedule change.","position":6,"audioStartSeconds":23.093416666666666,"audioEndSeconds":28.531541666666666},{"speaker":"A","text":"Thank you for your cooperation and enjoy the rest of your visit.","position":7,"audioStartSeconds":28.731541666666665,"audioEndSeconds":32.842375},{"speaker":"A","text":"Please listen carefully to this important instruction about your portable audio devices.","role":"section-start","position":8,"audioStartSeconds":37.842375,"audioEndSeconds":43.409375},{"speaker":"A","text":"All rented audio guides must be returned to the front desk before you leave.","position":9,"audioStartSeconds":43.609375,"audioEndSeconds":48.441833333333335},{"speaker":"A","text":"Drop your device into the wooden box near the exit doors.","position":10,"audioStartSeconds":48.64183333333333,"audioEndSeconds":52.68825},{"speaker":"A","text":"If you forgot your headphones please hand them directly to a staff member.","position":11,"audioStartSeconds":52.88825,"audioEndSeconds":57.48875},{"speaker":"A","text":"Visitors who keep the devices overnight will face an extra replacement fee.","position":12,"audioStartSeconds":57.68875,"audioEndSeconds":62.559875},{"speaker":"A","text":"Our reception team will provide a small discount voucher for your next museum entry.","position":13,"audioStartSeconds":62.759875,"audioEndSeconds":68.10783333333333},{"speaker":"A","text":"Have a wonderful evening and we hope to see you again soon.","position":14,"audioStartSeconds":68.30783333333333,"audioEndSeconds":72.21291666666667}],"questions":[{"prompt":"What is happening to the main exhibition hall today?","options":["It will open later than usual.","It will close early for maintenance.","It is permanently shutting down."],"answer":"B","evidenceSentence":2,"evidence":"The main exhibition hall on the second floor will close early for maintenance work.","explanation":"Thông báo cho biết sảnh triển lãm chính sẽ đóng cửa sớm để bảo trì."},{"prompt":"Where should visitors go by four o'clock?","options":["To the ground floor gift shop.","To the sculpture garden outside.","To the front entrance lobby."],"answer":"A","evidenceSentence":4,"evidence":"Please move toward the ground floor gift shop by four o'clock.","explanation":"Người nói hướng dẫn khách di chuyển về phía cửa hàng quà tặng ở tầng trệt trước bốn giờ."},{"prompt":"Which area remains open until five o'clock?","options":["The second floor gallery.","The indoor cafe area.","The sculpture garden."],"answer":"C","evidenceSentence":5,"evidence":"You can still view the sculpture garden outside until five o'clock.","explanation":"Khu vườn tượng bên ngoài vẫn mở cửa cho đến năm giờ."},{"prompt":"Where must visitors put their rented audio guides?","options":["Into the wooden box near the exit.","On the front desk counter.","Inside their personal bags."],"answer":"A","evidenceSentence":10,"evidence":"Drop your device into the wooden box near the exit doors.","explanation":"Thiết bị hướng dẫn âm thanh cần được bỏ vào chiếc hộp gỗ gần các cửa ra."},{"prompt":"What happens if a visitor keeps a device overnight?","options":["They receive a warning letter.","They pay an extra replacement fee.","Their membership gets cancelled."],"answer":"B","evidenceSentence":12,"evidence":"Visitors who keep the devices overnight will face an extra replacement fee.","explanation":"Giữ thiết bị qua đêm sẽ phải chịu một khoản phí thay thế bổ sung."},{"prompt":"What will the reception team give to returning visitors?","options":["A free art book.","A small discount voucher.","A printed map of the city."],"answer":"B","evidenceSentence":13,"evidence":"Our reception team will provide a small discount voucher for your next museum entry.","explanation":"Đội ngũ lễ tân sẽ cung cấp một phiếu giảm giá nhỏ cho lần vào bảo tàng tiếp theo."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
